            <div class="order-summary"><div class="checkout-breakdown"><span>Items subtotal</span><strong>{{ \App\Support\Money::format($order->subtotal_cents) }}</strong></div><div class="checkout-breakdown"><span>Delivery fee</span><strong>{{ \App\Support\Money::format($order->delivery_fee_cents) }}</strong></div><div class="total-row"><span>Order total</span><strong>{{ \App\Support\Money::format($order->total_cents) }}</strong></div><p class="field-help">{{ $order->sale_id ? 'Payment recorded. This amount is included in paid sales.' : ($order->status === 'cancelled' ? 'Cancelled. The stock reservation was released.' : 'Unpaid. Product quantities are reserved; this amount is excluded from sales revenue.') }}</p></div>
